-- domyślna tabela dla customów, jeśli jeszcze żadnej nie ma
update size_charts set default_for = 'custom' where id = '780979ae-8261-4c28-83cc-8c8c6b2cf70a' and not exists (select 1 from size_charts where default_for = 'custom');
update size_charts set default_for = 'pants' where id = '2b87a77f-8dac-4a24-862c-7e9232d1fa4d' and not exists (select 1 from size_charts where default_for = 'pants');
update size_charts set default_for = 'hats' where id = '816c585a-eda3-4d7f-8dd6-ac20fbea8a09' and not exists (select 1 from size_charts where default_for = 'hats');

on conflict (id) do nothing;

